"""Read-only share archive workspace; a single CSP-hashed script, no CDN."""
HTML=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>股份研究档案 · 稻草财经</title><style>
:root{--bg:#f5f6f8;--panel:#fff;--ink:#182433;--muted:#6f7c8d;--line:#e5eaf0;--accent:#5264db;--soft:#eef1ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}a{color:var(--accent);text-decoration:none}button{font:inherit;cursor:pointer;border:1px solid var(--line);border-radius:8px;padding:7px 12px;background:var(--panel);color:var(--ink)}button:disabled{opacity:.45;cursor:default}button:hover{border-color:var(--accent)}button,a{touch-action:manipulation;outline-offset:4px}header{height:58px;background:var(--panel);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 28px;gap:12px}header b{font-size:15px}.workspace{max-width:1320px;margin:auto;padding:24px 28px 48px}h1{margin:0;font-size:25px;letter-spacing:-.7px}h2{margin:0;font-size:18px}h3{margin:0;font-size:14px}p{margin:6px 0}.muted{color:var(--muted);font-size:12px}.intro{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}.layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:20px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:20px;min-width:0}.list{margin-top:12px}.record{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid var(--line);border-radius:0;padding:14px 0;background:none}.record b{display:block;overflow-wrap:anywhere}.record small{display:block;color:var(--muted);font-size:11px}.record[aria-current=true] b{color:var(--accent)}.row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.badge{display:inline-block;font-size:11px;color:var(--accent);background:var(--soft);border-radius:5px;padding:3px 7px}.metricgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:20px 0}.metric small{color:var(--muted);display:block;font-size:11px}.metric strong{overflow-wrap:anywhere;font-size:26px;line-height:1.5;font-variant-numeric:tabular-nums}.timeline{margin:18px 0;border-top:1px solid var(--line)}.timeline>div{display:grid;grid-template-columns:125px minmax(0,1fr);gap:10px;padding:11px 0;border-bottom:1px solid var(--line);font-size:12px}.timeline span{color:var(--muted)}.notice{padding:12px 14px;border-left:3px solid var(--accent);background:var(--soft);border-radius:0 8px 8px 0;font-size:12px;line-height:1.8;margin:16px 0}.empty{min-height:300px;display:grid;place-content:center;text-align:center;padding:30px;color:var(--muted)}.sectionhead{display:flex;justify-content:space-between;align-items:center;gap:12px}.reviews{margin-top:24px}.review{display:block;width:100%;text-align:left;margin:8px 0;padding:12px}.review span{display:block;font-size:11px;color:var(--muted)}.detail{overflow-wrap:anywhere}.hidden{display:none!important}#error{padding:12px 15px;border:1px solid #dfa9af;background:#fff2f2;color:#9c3440;border-radius:9px;margin-bottom:16px}footer{padding-top:24px;font-size:11px;color:var(--muted)}details{margin-top:16px}summary{cursor:pointer;color:var(--muted);font-size:12px}.digest{font:11px ui-monospace,monospace;overflow-wrap:anywhere}.back{margin-bottom:16px}@media(prefers-color-scheme:dark){:root{--bg:#10151d;--panel:#181f2b;--ink:#e4e9f2;--muted:#8e9aaf;--line:#293241;--accent:#94a1ff;--soft:#252c47}#error{background:#321e25;border-color:#66303c;color:#f1adb7}}@media(max-width:700px){header{padding:0 14px}.workspace{padding:18px 12px 36px}.layout{grid-template-columns:minmax(0,1fr);gap:14px}.panel{padding:16px}.intro{margin-bottom:15px}h1{font-size:22px}.list{max-height:240px;overflow:auto}.metricgrid{gap:10px}.metric strong{font-size:23px}.timeline>div{grid-template-columns:105px minmax(0,1fr)}.empty{min-height:220px}}
</style></head><body><header><b>稻草财经 <span class="muted">/ 股份档案</span></b><a href="/api/quant-research/workspace">策略工作台 ↗</a></header><div class="workspace"><div class="intro"><div><h1>每一份权益，都有来处。</h1><p class="muted">资料时点、待收股份与数量复核分别留档。</p></div><button id="reload">刷新档案</button></div><div id="error" role="alert" class="hidden"></div><div id="login" class="panel hidden">请先<a href="/">返回首页登录</a>，再查看你的研究档案。</div><div id="content" class="layout hidden"><aside class="panel"><div class="sectionhead"><h3>我的股份资料</h3><span class="badge">只读审阅</span></div><div id="bundles" class="list"></div><button id="next" class="hidden" style="margin-top:12px">更多资料</button></aside><main id="detail" class="panel detail"><div class="empty">选择一份资料，查看入库时间和复核记录。</div></main></div><footer>内部研究档案。假设持仓、人工快照与实际清算认证不同；数量模型不构成策略收益或交易许可。</footer></div><script>
'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token=()=>{try{return localStorage.getItem('auth_token')||''}catch{return ''}};
let owned=token(),generation=0,selection=0,bundleItems=[],nextCursor=null,activeBundle=null,reviewCursor=null,reviewItems=[];let listLoading=false;
const status=v=>({quantity_model_completed:'数量模型已完成',awaiting_allotment:'待获配确认',not_available_as_recorded:'当时资料不可用'}[v]||'状态待核对');
const role=v=>v==='counterfactual_model'?'假设持仓':v==='operator_supplied_account_close'?'人工账户快照':'来源待核对';
const mode=v=>v==='as_recorded'?'按当时系统留存':'事后重建 · 已见资料';
const date=v=>{if(!v)return '未知';const d=new Date(v);return Number.isNaN(d.getTime())?'未知':d.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})};
function report(e){if(!e.stale)error(e.message)}
function session(g,auth,epoch){if(g!==generation||auth!==token()||epoch!=null&&epoch!==selection){if(g===generation&&auth!==token())clear();const e=Error('Account changed');e.stale=true;throw e}}
function error(message){$('error').textContent=message;$('error').classList.toggle('hidden',!message)}
function clear(){listLoading=false;$('reload').disabled=false;$('next').disabled=false;generation++;selection++;bundleItems=[];reviewItems=[];activeBundle=null;nextCursor=null;reviewCursor=null;$('bundles').textContent='';$('detail').textContent='';$('content').classList.add('hidden');$('login').classList.toggle('hidden',!!token());$('next').classList.add('hidden');error('')}
async function api(path,epoch=null){const auth=token(),g=generation;if(!auth)throw Error('请先返回首页登录');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch('/api/quant-research'+path,{headers:{Authorization:'Bearer '+auth},signal:controller.signal,cache:'no-store'});session(g,auth,epoch);if(r.status===401){clear();$('login').classList.remove('hidden');throw Error('登录已过期，请返回首页重新登录')}if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error('档案服务暂不可用，请稍后重试');const data=await r.json();session(g,auth,epoch);if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'档案读取未完成');return data}finally{clearTimeout(timer)}}
function drawList(){$('bundles').innerHTML=bundleItems.map(b=>`<button class="record" data-bundle="${esc(b.id)}" aria-current="${b.id===activeBundle}"><b>${esc(b.label)}</b><small>${esc(b.symbol)} · ${esc(role(b.position_role))}</small><small>${esc(b.record_date)}登记 · ${b.source_version_current?'打开查看':'旧版本归档'}</small></button>`).join('')||'<p class="muted">暂无已导入资料。由内部管理员导入核对后的原文与数量计划。</p>';$('next').classList.toggle('hidden',!nextCursor)}
async function load(more=false){if(listLoading)return;const g=generation;error('');if(!token()){clear();return}listLoading=true;$('reload').disabled=true;$('next').disabled=true;try{const data=await api('/share-evidence'+(more&&nextCursor?'?cursor='+encodeURIComponent(nextCursor):''));if(g!==generation)return;bundleItems=more?[...new Map([...bundleItems,...data.items].map(b=>[b.id,b])).values()]:data.items;nextCursor=data.next_cursor;$('login').classList.add('hidden');$('content').classList.remove('hidden');drawList();if(!more){$('detail').innerHTML='<div class="empty">选择一份资料，查看入库时间和复核记录。</div>';activeBundle=null;reviewItems=[]}}finally{if(g===generation){listLoading=false;$('reload').disabled=false;$('next').disabled=false}}}
function timeline(label,value){return `<div><span>${esc(label)}</span><b>${esc(value)}</b></div>`}
function renderBundle(b){const a=b.action,clock=b.component_visibility;$('detail').innerHTML=`<div class="sectionhead"><div><h2>${esc(b.label)}</h2><p class="muted">${esc(b.symbol)} · ${esc(a.kind==='capital_reserve'?'资本公积转增':'送股数量研究')}</p></div><span class="badge">${esc(role(b.position_role))}</span></div><div class="notice">${b.source_version_current?'档案完整性已核对；字段由内部管理员提供，不代表实际清算认证。':'旧版本归档：保留原记录，不用当前代码冒充原版本复核。'}</div><div class="metricgrid"><div class="metric"><small>声明的登记持仓</small><strong>${Number(b.declared_old_shares)}</strong><small>股 · ${esc(role(b.position_role))}</small></div><div class="metric"><small>每股新增比例</small><strong>${esc(a.new_shares_per_old_share)}</strong><small>账户汇总后核对零碎权益</small></div><div class="metric"><small>留存原文</small><strong>${Number(b.source_count)}</strong><small>份 · 不公开下载原文</small></div></div><h3>时间与来源</h3><p class="muted">日期时间均按北京时间显示；事实生效日和系统可用日不能互换。</p><div class="timeline">${timeline('股权登记日',a.record_date)}${timeline('除权日',a.ex_date)}${timeline('股份入账日',a.share_credit_date)}${timeline('无限售可交易日',a.unrestricted_trade_date||'未知 · 不视为可卖')}${timeline('本份资料入库',date(b.recorded_at))}${timeline('公告首次系统可用',date(clock.action))}${timeline('快照首次系统可用',date(clock.position_snapshot))}${timeline('获配确认可用',clock.allotment?date(clock.allotment):'尚无单独获配确认')}</div><div class="reviews"><h3>数量复核记录</h3><div id="reviews"><p class="muted">正在读取…</p></div><button id="reviewMore" class="hidden">更多复核</button></div><details><summary>查看审计标识与范围</summary><p class="digest">${esc(b.fingerprint)}</p><p class="muted">完整经济事件、税基、现金净值与订单尚未接通，不开启模拟账户或真实交易。</p></details>`}
function drawReviews(){$('reviews').innerHTML=reviewItems.map(r=>`<button class="review" data-review="${esc(r.id)}">${esc(status(r.status))}<span>${esc(mode(r.mode))} · 视点 ${esc(date(r.as_of))}</span><span>${r.source_version_current?'查看数量核对':'旧版本归档'}</span></button>`).join('')||'<p class="muted">尚无归档复核记录；可由内部管理员执行并归档。</p>';$('reviewMore').classList.toggle('hidden',!reviewCursor)}
async function reviews(more=false){if(!activeBundle)return;const id=activeBundle,s=selection;const d=await api('/share-reviews?bundle_id='+encodeURIComponent(id)+(more&&reviewCursor?'&cursor='+encodeURIComponent(reviewCursor):''),s);if(s!==selection||id!==activeBundle)return;reviewItems=more?[...reviewItems,...d.items]:d.items;reviewCursor=d.next_cursor;drawReviews()}
async function selectBundle(id){const s=++selection;activeBundle=id;drawList();$('detail').textContent='正在核对档案…';const b=await api('/share-evidence/'+encodeURIComponent(id),s);if(s!==selection||id!==activeBundle)return;renderBundle(b);reviewItems=[];reviewCursor=null;await reviews();if(window.innerWidth<=700)$('detail').scrollIntoView({behavior:'auto',block:'start'})}
function numberMetric(label,value,sub){return `<div class="metric"><small>${esc(label)}</small><strong>${value==null?'—':esc(value)}</strong><small>${esc(sub)}</small></div>`}
function renderReview(r){const q=r.source_version_current&&r.verification_level==='evidence_and_quantity_checked'?r.quantity:null,reason=!r.source_version_current?'旧版本归档，未用当前代码重新验证数量。':r.status==='not_available_as_recorded'?'登记或入账时，所需资料尚未到达系统可用边界。不是断言没有权益。':r.status==='awaiting_allotment'?'账户仍有零碎待收权益，缺少获配确认；没有逐批取整或编造入账。':'数量模型已完成；不代表实际券商获配、税基或交易许可。';$('detail').innerHTML=`<button class="back" data-bundle="${esc(r.bundle_id)}">← 返回资料</button><div class="sectionhead"><div><h2>${esc(r.source_version_current?status(r.status):'旧版本复核记录')}</h2><p class="muted">${esc(r.label)} · ${esc(r.symbol)}<br>${esc(mode(r.mode))} · 视点 ${esc(date(r.as_of))}</p></div><span class="badge">${esc(role(r.position_role))}</span></div><div class="notice">${esc(reason)}</div><div class="metricgrid">${numberMetric('登记旧股',q?.registered_old_shares,'声明数量')}${numberMetric('已入账新增',q?.credited?Number(q.credited.unrestricted)+Number(q.credited.restricted):null,q?.credited?'股 · 数量模型':'尚未确认')}${numberMetric('新增无限售可用',q?q.available_new_unrestricted_shares:null,'仅库存条件，非交易许可')}</div>${q?.exact_new_shares?`<div class="timeline">${timeline('无限售精确权益',q.exact_new_shares.unrestricted)}${timeline('限售精确权益',q.exact_new_shares.restricted)}</div>`:''}<p class="muted">${r.source_version_current?'原文、来源关系和归档数量结果已核对。':'仅展示旧版归档元数据，数量留空。'}<br>复核入库 ${esc(date(r.recorded_at))}。假设持仓不是实际账户；尚未接通现金、税务、净值与订单。</p><details><summary>审计标识</summary><p class="digest">${esc(r.fingerprint)}</p></details>`}
async function selectReview(id){const s=++selection;$('detail').textContent='正在核对数量记录…';const r=await api('/share-reviews/'+encodeURIComponent(id),s);if(s!==selection)return;renderReview(r);if(window.innerWidth<=700)$('detail').scrollIntoView({behavior:'auto',block:'start'})}
$('reload').addEventListener('click',()=>{selection++;load().catch(report)});$('next').addEventListener('click',()=>load(true).catch(report));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.bundle)selectBundle(b.dataset.bundle).catch(report);if(b.dataset.review)selectReview(b.dataset.review).catch(report);if(b.id==='reviewMore')reviews(true).catch(report)});
window.addEventListener('storage',()=>{if(token()!==owned){owned=token();clear();load().catch(report)}});window.addEventListener('pagehide',()=>{generation++;selection++});load().catch(report);
</script></body></html>'''
